def cha2ds2_vasc(age, female, heart_failure, hypertension, diabetes, stroke_tia, vascular):
    score = 0

    # Age: ≥75 years
    if age >= 75:
        score += 1
    # Age: ≥80 years
    elif age >= 80:
        score += 2
    # Age: ≥90 years
    elif age >= 90:
        score += 3

    # Female sex
    if female:
        score += 1

    # History of heart failure
    if heart_failure:
        score += 2

    # History of hypertension
    if hypertension:
        score += 1

    # History of diabetes
    if diabetes:
        score += 1

    # History of stroke or TIA
    if stroke_tia:
        score += 1

    # Vascular disease
    if vascular:
        score += 1

    return score
